/// SSE body: the answer in two tokens, then [done] (default: the real one).
String p3ChatSse({Map<String, dynamic>? done}) {
  final d = done ?? p3ChatDone();
  final answer = '${(d['message'] as Map)['content']}';
  final half = answer.length ~/ 2;
  String ev(Map<String, dynamic> m) => 'data: ${jsonEncode(m)}\n\n';
  return [ev({'type': 'token', 'content': answer.substring(0, half)}), ev({'type': 'token', 'content': answer.substring(half)}), ev(d)].join();
}
